def snake_to_camel(name):
    stripped = name.lstrip("_")
    prefix = name[: len(name) - len(stripped)]
    words = [w for w in stripped.split("_") if w]
    if not words:
        return prefix
    return prefix + words[0].lower() + "".join(w[0].upper() + w[1:].lower() for w in words[1:])

